def compute(vars):
    average_value = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average_value,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "average_value": average_value,
            "output_meta": {
                "currency": "USD",
                "scale": "billions",
                "unit": None
            }
        }
    }
